#include <charconv>
#include <memory>
#include <utility>

bool appendBounded(std::vector<int>& values, int value, std::size_t limit) {
    // Logical size is the number of live values, not capacity.
    if (value < -100 || value > 100 || values.size() >= limit) return false;
    values.push_back(value);
    return true;
}

int main() {
    std::vector<int> v{3,4};
    std::cout<<std::boolalpha<<appendBounded(v,5,2)<<" "<<v.size()<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

std::pair<int,int> packing(int items, int group) {
    // Positive group size prevents division by zero.
    if (items < 0 || items > 1000 || group < 1 || group > 100) throw std::invalid_argument("range");
    return {items / group, items % group};
}

int main() {
    int n,g;
    if(!(std::cin>>n>>g))return 2;
    try{auto p=packing(n,g);
    std::cout<<p.first<<" "<<p.second<<"\n";
    }catch(const std::invalid_argument&){std::cout<<"range\n";
    }}

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

bool readCount(const std::string& text, int& output) {
    std::istringstream input(text);
    int candidate{};
    // Read a candidate, then check domain and complete consumption.
    if (!(input >> candidate) || candidate < 0 || candidate > 20) return false;
    input >> std::ws;
    if (!input.eof()) return false;
    output = candidate; // Commit only after every check succeeds.
    return true;
}

int main() {
    std::string text;
    std::getline(std::cin,text);
    int n=7;
    if(readCount(text,n))std::cout<<n<<"\n";
    else std::cout<<"invalid "<<n<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

int checkedNext(int value) {
    // Check the boundary before the potentially overflowing expression.
    if (value == std::numeric_limits<int>::max()) throw std::out_of_range("overflow");
    return value + 1;
}

int main() {
    int n;
    if(!(std::cin>>n))return 2;
    try{std::cout<<checkedNext(n)<<"\n";
    }catch(const std::out_of_range&){std::cout<<"overflow\n";
    }}

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

bool parseField(const std::string& text, int& output) {
    int candidate{};
    auto result = std::from_chars(text.data(), text.data() + text.size(), candidate);
    // Both conversion status and complete consumption are required.
    if (result.ec != std::errc{} || result.ptr != text.data() + text.size()) return false;
    if (candidate < 0 || candidate > 100) return false;
    output = candidate;
    return true;
}

int main() {
    std::string s;
    std::getline(std::cin,s);
    int n=8;
    if(parseField(s,n))std::cout<<n<<"\n";
    else std::cout<<"invalid "<<n<<"\n";
    }

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

class Interval {
    int low_, high_;
public:
    Interval(int low, int high) : low_(low), high_(high) {
        if (low < -100 || high > 100 || low > high) throw std::invalid_argument("range");
    }
    int low() const { return low_; }
    int high() const { return high_; }
};

int main() {
    try{Interval r(3,3);
    std::cout<<r.low()<<" "<<r.high()<<"\n";
    }catch(const std::invalid_argument&){std::cout<<"range\n";
    }}

#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <limits>
#include <stdexcept>
#include <sstream>
#include <charconv>
#include <memory>
#include <utility>

int* firstAbove(std::vector<int>& values, int threshold) {
    for (int& value : values) {
        if (value > threshold) return &value; // Borrow the actual element.
    }
    return nullptr;
}

int main() {
    std::vector<int> v{4,4,9};
    int* p=firstAbove(v,4);
    if(p)std::cout<<*p<<"\n";
    else std::cout<<"none\n";
    }

